const std = @import("std");

// Simple xorshift64 RNG
const Xorshift64 = struct {
    var state: u64;

    pub fn init(seed: u64) Xorshift64 {
        return Xorshift64{state: @as(u64, if (seed == 0) seed + 1 else seed)};
    }

    pub fn next(self: Xorshift64) u64 {
        var x = self.state;
        const s = x;
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 16;
        self.state = x;
        return x;
    }
};
```

