        var x = self.state;
        const s0 = x;
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 16;
        self.state = x;
        return x;
    }

    pub fn next_range(self: Xorshift64, min: i8, max: i8) i8 {
        var range = @usize(max) - @usize(min) + 1;
        var r = self.next_u64();
        // Modular reduction (not perfect but good enough for this exercise)
        var result = @usize(min) + (r % @usize(range));
        return @as(i8, result);
    }
};
